spec.test_code:
import assert from 'node:assert/strict';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { SkillBadge } from './SkillBadge.mjs';

const html1 = renderToStaticMarkup(React.createElement(SkillBadge, { name: 'Python', mastery: 85 }));
assert.match(html1, /class="skill-badge"/);
assert.match(html1, /<strong>Python<\/strong>/);
assert.match(html1, /data-tier="master"/);
assert.match(html1, /85%/);

const html2 = renderToStaticMarkup(React.createElement(SkillBadge, { name: 'Regex', mastery: 20 }));
assert.match(html2, /data-tier="novice"/);

const html3 = renderToStaticMarkup(React.createElement(SkillBadge, { name: 'SQL', mastery: 55 }));
assert.match(html3, /data-tier="adept"/);
console.log('React component tests passed!');

