starter_files.challenge.spec.mjs:
import assert from 'node:assert/strict';
import { chromium } from 'playwright';

const browser = await chromium.launch();
try {
  const page = await browser.newPage();
  await page.goto(process.env.TARGET_URL);
  // TODO: fill 'Prompt' with 'hello nvim', click 'Score', and assert data-testid='out'
  const out = await page.getByTestId('out').textContent();
  assert.equal(out, 'Scored: HELLO NVIM');
  console.log('Playwright E2E passed!');
} finally {
  await browser.close();
}
